// Regenerates src/generated/* from the vendored Cal.diy OpenAPI spec.
//   bun scripts/generate.ts          write the generated files
//   bun scripts/generate.ts --check  fail if they are out of date (used in CI)
import { createHash } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";

import openapiTS, { astToString } from "openapi-typescript";

const SPEC_FILE = new URL("../openapi/cal-diy-api-v2.json", import.meta.url);
const SOURCE_FILE = new URL("../openapi/SOURCE.json", import.meta.url);
const TYPES_FILE = new URL("../src/generated/openapi.d.ts", import.meta.url);
const VERSIONS_FILE = new URL("../src/generated/api-versions.ts", import.meta.url);

const HEADER =
  "// Generated by packages/cal-api/scripts/generate.ts from openapi/cal-diy-api-v2.json. Do not edit by hand.\n";

const HTTP_METHODS = ["get", "put", "post", "delete", "options", "head", "patch", "trace"] as const;

type Parameter = {
  in?: string;
  name?: string;
  description?: string;
  schema?: { default?: unknown };
};

type Operation = {
  operationId?: string;
  parameters?: Parameter[];
};

type Spec = {
  paths: Record<string, Partial<Record<(typeof HTTP_METHODS)[number], Operation>>>;
};

type SourceInfo = {
  commit: string;
  sha256: string;
};

// Most operations declare the version as the header's default; a few only say it in the description
// ("Must be set to 2024-08-13"). An operation without the header must be called without it.
function apiVersionOf(operation: Operation, label: string): string | null {
  const header = operation.parameters?.find((p) => p.in === "header" && p.name === "cal-api-version");
  if (!header) return null;
  if (typeof header.schema?.default === "string") return header.schema.default;
  const fromDescription = header.description?.match(/Must be set to (\d{4}-\d{2}-\d{2})/)?.[1];
  if (fromDescription) return fromDescription;
  throw new Error(`${label} has a cal-api-version header, but no version could be read from it.`);
}

export function buildVersionsModule(spec: Spec): string {
  const lines: string[] = [];
  for (const path of Object.keys(spec.paths).sort()) {
    const item = spec.paths[path] ?? {};
    for (const method of HTTP_METHODS) {
      const operation = item[method];
      if (!operation) continue;
      const key = `${method.toUpperCase()} ${path}`;
      const version = apiVersionOf(operation, key);
      lines.push(`  ${JSON.stringify(key)}: ${JSON.stringify(version)}, // ${operation.operationId ?? ""}`);
    }
  }
  return `${HEADER}
// cal-api-version to send for each operation, keyed by "METHOD /schema/path". null means send no header.
export const API_VERSIONS = {
${lines.join("\n")}
} as const satisfies Record<string, string | null>;
`;
}

// The client adds these to every request, so the generated types shouldn't make each call pass them.
const CLIENT_INJECTED_HEADERS = new Set(["authorization", "cal-api-version"]);

// Adjusts a copy of the spec for type generation only; the version map is built from the original.
// - Drops the headers the client injects.
// - Cal.diy reuses two operationIds for the legacy /v2/calendars/{calendar}/event/{eventUid} paths, and
//   openapi-typescript needs unique ids (they key the `operations` type), so later duplicates get a suffix.
export function prepareSpecForTypes(spec: Spec): Spec {
  const copy = structuredClone(spec);
  const seenOperationIds = new Map<string, number>();
  for (const path of Object.keys(copy.paths)) {
    const item = copy.paths[path] ?? {};
    for (const method of HTTP_METHODS) {
      const operation = item[method];
      if (!operation) continue;

      operation.parameters = operation.parameters?.filter(
        (p) => !(p.in === "header" && CLIENT_INJECTED_HEADERS.has((p.name ?? "").toLowerCase()))
      );

      if (!operation.operationId) continue;
      const count = (seenOperationIds.get(operation.operationId) ?? 0) + 1;
      seenOperationIds.set(operation.operationId, count);
      if (count > 1) operation.operationId = `${operation.operationId}_${count}`;
    }
  }
  return copy;
}

async function buildTypesModule(spec: Spec): Promise<string> {
  // Passed as JSON text: openapiTS types its object input as its own OpenAPI3 document type.
  const ast = await openapiTS(JSON.stringify(prepareSpecForTypes(spec)));
  return `${HEADER}${astToString(ast)}`;
}

async function main() {
  const check = process.argv.includes("--check");
  const specText = await readFile(SPEC_FILE, "utf8");
  const source = JSON.parse(await readFile(SOURCE_FILE, "utf8")) as SourceInfo;

  const actualSha256 = createHash("sha256").update(specText).digest("hex");
  if (actualSha256 !== source.sha256) {
    throw new Error(
      `openapi/cal-diy-api-v2.json does not match the sha256 in openapi/SOURCE.json. Run "bun run sync-openapi" instead of editing the spec by hand.`
    );
  }

  const spec = JSON.parse(specText) as Spec;
  const outputs: Array<[URL, string]> = [
    [TYPES_FILE, await buildTypesModule(spec)],
    [VERSIONS_FILE, buildVersionsModule(spec)],
  ];

  if (check) {
    const stale: string[] = [];
    for (const [file, contents] of outputs) {
      const current = await readFile(file, "utf8").catch(() => "");
      if (current !== contents) stale.push(file.pathname);
    }
    if (stale.length > 0) {
      console.error(`Generated files are out of date:\n${stale.join("\n")}\nRun "bun run generate".`);
      process.exit(1);
    }
    console.log(`Generated files match calcom/cal.diy@${source.commit.slice(0, 7)}.`);
    return;
  }

  for (const [file, contents] of outputs) {
    await writeFile(file, contents);
  }
  console.log(`Generated files from calcom/cal.diy@${source.commit.slice(0, 7)}.`);
}

if (import.meta.main) {
  await main();
}
